def check_condition(n):
    if n < 0:
        return False

    divisor = 2 * n - 1

    if divisor == 0:
        # This case is impossible since 2n-1 = 0 implies n=0.5, but n is integer.
        # For n=0, divisor is -1.
        pass

    numerator = 3 * ((n + 2) * (n + 1) * 1) # Start calculating (n+2)!

    import math

    try:
        n_plus_2_factorial = math.factorial(n + 2)
    except OverflowError:
        # Handle extremely large factorials if needed, though likely not necessary for small checks
        return None 

    numerator = 3 * (n_plus_2_factorial + 1)

    if numerator % divisor == 0:
        return True
    else:
        return False

solutions = []
for n in range(10):
    if check_condition(n):
        solutions.append(n)

print(f"Solutions found for n=0 to n=9: {solutions}")

